function resolveHighlightClass() {
  const modPath = path.resolve(process.cwd(), 'src', 'display', 'editor', 'drawers', 'highlight.js');
  const mod = require(modPath);

  // Direct constructor export
  if (typeof mod === 'function') return mod;

  // Named export
  if (typeof mod?.HighlightOutline === 'function') return mod.HighlightOutline;

  // Default export
  if (typeof mod?.default === 'function') return mod.default;

  // Fallback: search through exports for a function with serialize method
  if (mod && typeof mod === 'object') {
    for (const key of Object.keys(mod)) {
      const val = mod[key];
      if (typeof val === 'function' && typeof val.prototype?.serialize === 'function') {
        return val;
      }
    }
  }
  throw new Error('HighlightOutline class could not be resolved from module');
}

