      [0.5, 0.25, 0.75, 0.9]
    ];
    const blX = 2;
    const blY = 3;
    const trX = 8;
    const trY = 11;
    const instance = new HighlightOutline(outlines, {}, null, null);
    const result = instance.serialize([blX, blY, trX, trY], 0);

    const width = trX - blX; // 6
    const height = trY - blY; // 8

    const expected = [
      [blX + 0 * width, trY - 0 * height, blX + 1 * width, trY - 1 * height], // [2, 11, 8, 3]
      [blX + 0.5 * width, trY - 0.25 * height, blX + 0.75 * width, trY - 0.9 * height] // [5, 9, 6.5, 3.8]
    ];

